h1{margin:0 0 6px;font-size:28px}.sub{color:var(--muted);margin:0 0 14px}
.bn{display:flex;gap:10px;align-items:center;border-radius:18px;padding:12px 14px;margin:0 0 10px;font-weight:800;border:2px solid}
.bn.new{background:#fff8e6;border-color:#f0c36d;color:#6b4800}.bn.soon{background:#fff1ef;border-color:#eba59f;color:#8a2a24}.bn a{margin-inline-start:auto}
.task{background:#fff;border:2px solid var(--line);border-radius:18px;padding:12px 14px;margin:0 0 10px}.task h3{margin:0 0 4px;font-size:19px}
.task .meta{color:var(--muted);font-size:14px}.it{display:flex;align-items:center;gap:10px;padding:8px 0;border-top:1px solid var(--line)}.it a.btn{margin-inline-start:auto}
.ok{color:#2f5f10;font-weight:800}.no{color:#8a2a24;font-weight:800}.tag{display:inline-block;border-radius:999px;padding:1px 10px;font-weight:800;font-size:13px}
.t-done{background:#e3f4d7;color:#2f5f10}.t-late{background:#ffd2cc;color:#8a2a24}.t-new{background:#ffe7a8;color:#6b4800}.t-open{background:#eef3f8;color:#2d4f70}
.badge{display:inline-grid;place-items:center;min-width:24px;height:24px;border-radius:12px;background:#d9534f;color:#fff;font-size:14px;padding:0 6px;margin-inline-start:4px}
.mine{background:#eef3f8;color:#2d4f70}
